insert into stijlen (id, naam, sub, positie) values
  ('klassiek', 'Klassiek', 'Opera, lied, oratorium', 0),
  ('musical', 'Musical', 'Musicaltheater, cabaret', 1),
  ('pop', 'Pop', 'Pop, R&B, covers', 2),
  ('rock', 'Rock & metal', 'Rauw, luid, distortion', 3),
  ('jazz', 'Jazz', 'Standards, scat, swing', 4),
