  ('gospel', 'Gospel & soul', 'Gospel, soul, worship', 7);
insert into niveaus (id, naam, sub, positie) values
  ('beginner', 'Beginner', 'Ik zing minder dan 2 jaar of zonder les', 0),
  ('gevorderd', 'Gevorderd', 'Ik zing al een tijd of volg zangles', 1),
  ('pro', 'Professioneel', 'Ik zing (semi)professioneel of studeer zang', 2);
insert into instellingen (sleutel, waarde) values ('duren', '[{"min":5,"sub":"Snel, voor een repetitie"},{"min":10,"sub":"Aanbevolen voor de meeste zangers"},{"min":15,"sub":"Uitgebreid, voor een optreden"}]'::jsonb);
insert into oefeningen (id, titel, soort, cat, duur, stijlen, niveau, klank, kort, stappen, letop, waarom, video) values ('schouders', 'Schouders en nek losmaken', array['op']::text[], 'lichaam', 60, array['alle']::text[], null, '—', 'Laat spanning uit je schouders en nek zakken.', array['Ga rechtop staan met je voeten op heupbreedte.','Trek je schouders op naar je oren en laat ze in één keer vallen. Doe dit 5 keer.','Rol je schouders langzaam 5 keer naar achteren.','Laat je hoofd rustig van links naar rechts hangen, zonder te forceren.']::text[], 'Beweeg rustig. Voel je pijn, stop dan.', 'Spanning in nek en schouders werkt door tot in je strottenhoofd en maakt je klank strakker.', '');
insert into oefeningen (id, titel, soort, cat, duur, stijlen, niveau, klank, kort, stappen, letop, waarom, video) values ('kaak', 'Kaakmassage', array['op']::text[], 'lichaam', 60, array['alle']::text[], null, '[ha]', 'Maak je kaakspieren los met je vingertoppen.', array['Leg je vingertoppen op je kaakspier, net voor je oren.','Masseer met kleine cirkels terwijl je mond licht open hangt.','Laat je kaak op het einde zwaar zakken en zucht op [ha].']::text[], 'Duw niet te hard. Het moet prettig blijven.', 'Een losse kaak geeft je klank en je tong meer ruimte.', '');
insert into oefeningen (id, titel, soort, cat, duur, stijlen, niveau, klank, kort, stappen, letop, waarom, video) values ('sss', 'Uitademen op sss', array['op']::text[], 'adem', 90, array['alle']::text[], null, '[s]', 'Train een rustige, gelijkmatige uitademing.', array['Leg een hand op je buik.','Adem in door je neus en voel je buik en flanken uitzetten.','Adem uit op een lange, gelijkmatige [s] van 8 tellen.','Verleng elke ronde met 2 tellen, tot 16 tellen.']::text[], 'Houd je schouders laag tijdens het inademen.', 'Een gelijkmatige luchtstroom is de basis voor een stabiele toon.', '');
insert into oefeningen (id, titel, soort, cat, duur, stijlen, niveau, klank, kort, stappen, letop, waarom, video) values ('staccato', 'Staccato op ha', array['op']::text[], 'adem', 60, array['klassiek','musical','gospel','koor']::text[], null, '[ha]', 'Korte, veerkrachtige impulsen vanuit je buik.', array['Leg je handen op je flanken.','Zeg 5 korte [ha]’s na elkaar en voel je buik bij elke [ha] intrekken.','Herhaal op een comfortabele toonhoogte, daarna een toon hoger.']::text[], 'Hou je keel open: de impuls komt uit je buik, niet uit je keel.', 'Activeert je ademsteun voor krachtige inzetten.', '');
insert into oefeningen (id, titel, soort, cat, duur, stijlen, niveau, klank, kort, stappen, letop, waarom, video) values ('lippentril', 'Lippentril op glijtoon', array['op']::text[], 'sovt', 90, array['alle']::text[], null, '[brr]', 'Laat je lippen trillen terwijl je van laag naar hoog glijdt.', array['Ontspan je lippen en blaas tot ze gaan trillen, zoals een paard.','Voeg een toon toe in je spreekhoogte.','Glijd langzaam omhoog en weer omlaag.','Maak de glijtoon elke ronde iets groter.']::text[], 'Lukt de tril niet? Duw zacht met twee vingers je wangen naar voren.', 'Een halfgesloten mond zorgt voor tegendruk, zodat je stemplooien soepel en zonder druk trillen.', '');
insert into oefeningen (id, titel, soort, cat, duur, stijlen, niveau, klank, kort, stappen, letop, waarom, video) values ('rietje', 'Zingen door een rietje', array['op','af']::text[], 'sovt', 120, array['alle']::text[], null, '[u] door rietje', 'Neurie of zing een melodie door een rietje.', array['Neem een rietje tussen je lippen. Sluit je lippen er goed omheen.','Maak een zachte [u] door het rietje.','Glijd op en neer, of zing een eenvoudig liedje door het rietje.','Hou je wangen en nek ontspannen.']::text[], 'Een dunner rietje geeft meer weerstand. Begin met een gewoon drinkrietje.', 'Een van de best onderzochte oefeningen om je stem zowel op te warmen als te laten herstellen.', '');
insert into oefeningen (id, titel, soort, cat, duur, stijlen, niveau, klank, kort, stappen, letop, waarom, video) values ('neurien', 'Neuriën op mmm', array['op']::text[], 'resonantie', 60, array['alle']::text[], null, '[m]', 'Voel trilling rond je lippen en neus.', array['Sluit je lippen zacht, tanden los van elkaar.','Neurie op een comfortabele toon.','Zoek de toon waarbij je de meeste trilling rond je lippen voelt.','Glijd van daaruit een paar tonen omhoog en omlaag.']::text[], 'Je lippen mogen kriebelen. Dat is goed.', 'Brengt je klank naar voren, wat helderheid geeft zonder extra kracht.', '');
insert into oefeningen (id, titel, soort, cat, duur, stijlen, niveau, klank, kort, stappen, letop, waarom, video) values ('twang', 'Twang op njee', array['op']::text[], 'resonantie', 60, array['musical','pop','rock','gospel']::text[], null, '[ɲɛ]', 'Een heldere, snijdende klank, zoals een eend of een plagend kind.', array['Zeg [njee] op een hoge, nasale manier, alsof je iemand plaagt.','Zing het op drie oplopende tonen.','Haal het nasale weg en hou de helderheid vast.']::text[], 'Het moet licht en makkelijk aanvoelen, niet geknepen.', 'Twang geeft volume en draagkracht met minder inspanning.', '');
insert into oefeningen (id, titel, soort, cat, duur, stijlen, niveau, klank, kort, stappen, letop, waarom, video) values ('sirene', 'Sirene op ng', array['op']::text[], 'bereik', 90, array['alle']::text[], null, '[ŋ]', 'Glijd als een sirene door je hele bereik.', array['Zeg [ng] zoals aan het eind van "zingen". Je tong raakt achteraan je verhemelte.','Glijd van laag naar hoog en terug.','Laat de overgangen in je stem gewoon gebeuren.']::text[], 'Ga niet hoger dan comfortabel. Elke dag een beetje is genoeg.', 'Verbindt borst- en kopstem en maakt de overgang soepeler.', '');
insert into oefeningen (id, titel, soort, cat, duur, stijlen, niveau, klank, kort, stappen, letop, waarom, video) values ('vijftoon', 'Vijftonige ladder op mi-me-ma', array['op']::text[], 'bereik', 120, array['klassiek','koor','musical','jazz']::text[], null, '[mi me ma mo mu]', 'Een klassieke toonladder van vijf tonen, op en af.', array['Zing do-re-mi-fa-sol-fa-mi-re-do op [mi me ma mo mu].','Begin in je comfortabele middenligging.','Schuif telkens een halve toon op.','Keer terug zodra het zwaar begint te voelen.']::text[], 'Hou elke klinker even rond en open.', 'Traint gelijkmatige klinkers over je bereik.', '');
insert into oefeningen (id, titel, soort, cat, duur, stijlen, niveau, klank, kort, stappen, letop, waarom, video) values ('octaaf', 'Octaafsprong op ja', array['op']::text[], 'bereik', 90, array['pop','musical','gospel','rock','folk']::text[], array['gevorderd','pro']::text[], '[ja]', 'Spring een octaaf omhoog en glijd terug.', array['Zing [ja] op een lage toon.','Spring een octaaf omhoog.','Glijd langzaam terug naar beneden.','Schuif een halve toon op en herhaal.']::text[], 'Hou je kin laag als je omhoog springt.', 'Maakt grote sprongen in je repertoire makkelijker.', '');
insert into oefeningen (id, titel, soort, cat, duur, stijlen, niveau, klank, kort, stappen, letop, waarom, video) values ('tongbreker', 'Tongbrekers', array['op']::text[], 'articulatie', 60, array['alle']::text[], null, '—', 'Een losse tong en lippen voor een duidelijke tekst.', array['Zeg langzaam: "De kat krabt de krollen van de trap."','Zeg daarna: "Liesje leerde Lotje lopen langs de lange Lindelaan."','Versnel elke ronde een beetje.','Zing ze daarna op één toon.']::text[], 'Duidelijk is belangrijker dan snel.', 'Je publiek moet je tekst verstaan, ook bij snelle passages.', '');
insert into oefeningen (id, titel, soort, cat, duur, stijlen, niveau, klank, kort, stappen, letop, waarom, video) values ('tong', 'Kauwend neuriën', array['op']::text[], 'articulatie', 60, array['alle']::text[], null, '[m]', 'Neurie terwijl je overdreven kauwt.', array['Neurie op [m] op een comfortabele toon.','Kauw ondertussen overdreven, alsof je een grote kauwgom hebt.','Laat je tong vrij bewegen in je mond.']::text[], 'Hou je schouders los terwijl je kauwt.', 'Ontspant tong, kaak en lippen tegelijk.', '');
insert into oefeningen (id, titel, soort, cat, duur, stijlen, niveau, klank, kort, stappen, letop, waarom, video) values ('belt', 'Van roepen naar zingen', array['op']::text[], 'stijl', 90, array['musical','pop','rock','gospel']::text[], array['gevorderd','pro']::text[], '[hej]', 'Voorbereiding op belten: een krachtige, spraakachtige klank.', array['Roep "hey!" naar iemand aan de overkant van de straat.','Doe dit op een vaste toon.','Houd de toon twee tellen aan zonder kracht te verliezen.','Schuif een halve toon op.']::text[], 'Voel je druk in je keel? Neem een stap terug naar een lagere toon.', 'Zoekt de krachtige klank van belten zonder te persen.', '');
insert into oefeningen (id, titel, soort, cat, duur, stijlen, niveau, klank, kort, stappen, letop, waarom, video) values ('scat', 'Scat-ritme', array['op']::text[], 'stijl', 90, array['jazz']::text[], null, '[du ba di]', 'Speel met ritme en lettergrepen op een swingend patroon.', array['Tik een rustige swing op je been.','Zing [du-ba-di-ba] op één toon in het ritme.','Varieer met de toonhoogte en met accenten.']::text[], 'Lichtheid gaat boven volume.', 'Warmt je ritmegevoel en lichte articulatie op.', '');
insert into oefeningen (id, titel, soort, cat, duur, stijlen, niveau, klank, kort, stappen, letop, waarom, video) values ('koorklank', 'Samen op één oe', array['op']::text[], 'stijl', 90, array['koor','klassiek']::text[], null, '[u]', 'Stem je klank af op een lange, rustige [u].', array['Zet een bromtoon aan of laat een toon spelen.','Zing een zachte [u] op dezelfde toon.','Luister of je klank versmelt met de bromtoon.','Maak de klank geleidelijk iets voller.']::text[], 'Luisteren is net zo belangrijk als zingen.', 'Traint zuiver zingen en samenklank.', '');
insert into oefeningen (id, titel, soort, cat, duur, stijlen, niveau, klank, kort, stappen, letop, waarom, video) values ('stillelach', 'Stille lach', array['op']::text[], 'stijl', 60, array['rock']::text[], array['gevorderd','pro']::text[], '—', 'Maak ruimte in je keel voor rauwe klanken.', array['Lach zonder geluid, alsof je in de bibliotheek bent.','Voel hoe je keel ruim en open wordt.','Hou dat gevoel vast en zeg zacht [a].']::text[], 'Doe distortion enkel onder begeleiding. Rauw mag nooit pijn doen.', 'Leert je keel open houden, zodat je veiliger kunt schreeuwen.', '');
insert into oefeningen (id, titel, soort, cat, duur, stijlen, niveau, klank, kort, stappen, letop, waarom, video) values ('spreekzang', 'Van praten naar zingen', array['op']::text[], 'stijl', 60, array['folk','pop','jazz']::text[], null, '—', 'Zeg een zin uit je lied en zing hem daarna op dezelfde plek.', array['Kies een zin uit een lied dat je straks zingt.','Zeg de zin op een natuurlijke spreektoon.','Zing hem nu met dezelfde ontspannenheid.']::text[], 'Je zang moet even makkelijk voelen als praten.', 'Zorgt voor een natuurlijke, persoonlijke klank.', '');
insert into oefeningen (id, titel, soort, cat, duur, stijlen, niveau, klank, kort, stappen, letop, waarom, video) values ('zucht', 'Zuchten en gapen', array['af']::text[], 'ontspanning', 60, array['alle']::text[], null, '[ha]', 'Laat je stem zakken met een diepe zucht.', array['Gaap met je mond dicht. Voel je keel ruim worden.','Zucht daarna hoorbaar van hoog naar laag op [ha].','Herhaal 5 keer, steeds zachter.']::text[], 'Druk niet op het einde van de zucht. Laat hem uitlopen.', 'Ontspant je strottenhoofd na het zingen.', '');
insert into oefeningen (id, titel, soort, cat, duur, stijlen, niveau, klank, kort, stappen, letop, waarom, video) values ('dalend', 'Dalende glijtonen op oe', array['af']::text[], 'afbouw', 90, array['alle']::text[], null, '[u]', 'Zachte glijtonen van boven naar beneden.', array['Begin iets boven je spreekhoogte.','Glijd zacht naar beneden op [u].','Begin elke keer een beetje lager.','Eindig in je spreekhoogte.']::text[], 'Zo zacht als je kunt, zonder te fluisteren.', 'Brengt je stem terug naar je spreekhoogte.', '');
insert into oefeningen (id, titel, soort, cat, duur, stijlen, niveau, klank, kort, stappen, letop, waarom, video) values ('neurielaag', 'Zacht neuriën in je spreekhoogte', array['af']::text[], 'afbouw', 60, array['alle']::text[], null, '[m]', 'Neurie zacht zoals je zou zeggen "mm-hm".', array['Zeg "mm-hm" alsof je instemt met iemand.','Neurie verder op die toon.','Laat de toon langzaam wegsterven.']::text[], 'Dit is geen oefening om sterker te worden. Rustig is goed.', 'Zet je stem terug in je spreekstand.', '');
insert into oefeningen (id, titel, soort, cat, duur, stijlen, niveau, klank, kort, stappen, letop, waarom, video) values ('trilaf', 'Lippentril naar beneden', array['af']::text[], 'sovt', 60, array['alle']::text[], null, '[brr]', 'Lippentril van hoog naar laag, steeds zachter.', array['Begin een lippentril in je middenligging.','Glijd langzaam naar beneden.','Maak elke ronde de glijtoon kleiner en zachter.']::text[], 'Ontspannen lippen. Gebruik je vingers als de tril niet lukt.', 'Masseert je stemplooien zacht na een inspanning.', '');
insert into oefeningen (id, titel, soort, cat, duur, stijlen, niveau, klank, kort, stappen, letop, waarom, video) values ('stretch', 'Nek- en schouderstretch', array['af']::text[], 'lichaam', 90, array['alle']::text[], null, '—', 'Rek de spieren die tijdens het zingen hard gewerkt hebben.', array['Leg je rechteroor rustig richting je rechterschouder. Hou 15 tellen.','Wissel naar links.','Vouw je handen achter je rug en open je borst. Hou 15 tellen.']::text[], 'Adem rustig door tijdens het rekken.', 'Na het optreden zit er vaak spanning in je nek en schouders.', '');
insert into oefeningen (id, titel, soort, cat, duur, stijlen, niveau, klank, kort, stappen, letop, waarom, video) values ('rust', 'Stemrust en water', array['af']::text[], 'rust', 60, array['alle']::text[], null, '—', 'Een minuut stilte en een glas water.', array['Ga zitten.','Drink een glas water in kleine slokjes.','Praat een minuut niet. Adem rustig door je neus.']::text[], 'Fluister niet tijdens stemrust. Fluisteren is vermoeiend voor je stem.', 'Je stem herstelt het best in stilte.', '');
